402	
403	    private void BuildHud(ContentManager content)
404	    {
405	        var squareButtons = content.Load<Texture2D>("SproutLands/Buttons/square_26x26");
406	        var settingsSheet = content.Load<Texture2D>("SproutLands/Buttons/settings_buttons");
407	
408	        DemoHeader.Build(
409	            _world, _viewportManager, _font, squareButtons,
410	            title: "camera",
411	            descriptionLines: new[]
412	            {
413	                "Use keyboard keys 0 to 5 to switch the camera target",
414	                "and the L key to toggle camera lerp.",
415	                "Use the WASD keys to control the red dot.",
416	            });
417	
418	        BuildSidebar(squareButtons, settingsSheet);
419	    }
420	
421	    private void BuildSidebar(Texture2D squareButtons, Texture2D settingsSheet)
422	    {
423	        var capStyle = new KeyCapStyle
424	        {
425	            SpriteSheet = squareButtons,
426	            DefaultSource = SproutSquareButtons.CreamLight,
427	            HoverSource   = SproutSquareButtons.CreamDark,
428	            ActiveSource  = SproutSquareButtons.TanDark,
429	            // 42 matches the lerp toggle pill width so all sidebar elements
430	            // line up on a shared left edge.
431	            CapPixels = 42,
432	            CapLabelScale = 0.22f,
433	            CapLabelColor = SproutPalette.WarmBrown,
434	        };
435	        var rowStyle = new KeyRowStyle
436	        {
437	            LabelColor = SproutPalette.TextLight,
438	            HoverColor = SproutPalette.TextHover,
439	            ActiveColor = SproutPalette.TextSelected,
440	            LabelScale = 0.18f,
441	            Gap = 10f,
442	            BackgroundColor = SproutPalette.DarkBgSecondary,
443	            HoverBackgroundColor = SproutPalette.DarkBgSecondary,
444	            ActiveBackgroundColor = SproutPalette.DarkBgSecondary,
445	            BackgroundPaddingX = 10f,
446	            BackgroundPaddingY = 6f,
447	        };
448	
449	        (Entity Container, Entity Outline, Vector2 Size) Row(string id, string key, string label) =>
450	            _world.CreateKeyRow(id, key, label, _font, capStyle, rowStyle, layerDepth: 0.96f);
451	
452	        // Order: 0 follow, 1 TL, 2 TR, 3 BR, 4 BL, 5 center.
453	        var follow = Row("mode.follow", "0", "follow red dot");
454	        var tl     = Row("mode.tl",     "1", "top-left");
455	        var tr     = Row("mode.tr",     "2", "top-right");
456	        var br     = Row("mode.br",     "3", "bottom-right");
457	        var bl     = Row("mode.bl",     "4", "bottom-left");
458	        var center = Row("mode.center", "5", "center");
459	
460	        // Toggle pill native is 28x18 (aspect ~1.56). Draw at 42x27 = native × 1.5
461	        // so the aspect ratio is preserved and the pill scales to match the cap chip.
462	        var lerp = _world.CreateToggleRow(
463	            id: "toggle.lerp",
464	            rowLabel: "smooth lerp",
465	            font: _font,
466	            toggleSheet: settingsSheet,
467	            offSource: SproutSettings.ToggleOff,
468	            onSource: SproutSettings.ToggleOn,
469	            initiallyOn: _lerpSmooth,
470	            toggleSize: new Vector2(42, 27),
471	            row: rowStyle,
472	            layerDepth: 0.96f);
473	
474	        _sidebarButtons[Mode.Follow]      = follow.Outline;
475	        _sidebarButtons[Mode.FixedTL]     = tl.Outline;
476	        _sidebarButtons[Mode.FixedTR]     = tr.Outline;
477	        _sidebarButtons[Mode.FixedBR]     = br.Outline;
478	        _sidebarButtons[Mode.FixedBL]     = bl.Outline;
479	        _sidebarButtons[Mode.FixedCenter] = center.Outline;
480	        _lerpToggle = lerp.Outline;
481	
482	        const float rowGap = 6f;       // gap BETWEEN per-row backgrounds
483	        const float groupGap = 16f;    // larger gap before the lerp toggle group
484	
485	        new AutoLayoutBuilder(_world, _viewportManager)
486	            .CreateRoot(ScreenAnchor.TopLeft, RenderTargetID.HUD)
487	            .Direction(LayoutDirection.Vertical)
488	            .Gap(rowGap)
489	            // Screen-root stacks roots vertically, so the sidebar already lands
490	            // below the header automatically — just add a small breathing pad.
491	            .Padding(20 /* top */, 12 /* right */, 12 /* bottom */, 12 /* left */)
492	            .AlignCross(CrossAxisAlignment.Start)
493	            .AddSlot(slot => slot.Attach(follow.Container).MeasureWith(_ => follow.Size))
494	            .AddSlot(slot => slot.Attach(tl.Container).MeasureWith(_ => tl.Size))
495	            .AddSlot(slot => slot.Attach(tr.Container).MeasureWith(_ => tr.Size))
496	            .AddSlot(slot => slot.Attach(br.Container).MeasureWith(_ => br.Size))
497	            .AddSlot(slot => slot.Attach(bl.Container).MeasureWith(_ => bl.Size))
498	            .AddSlot(slot => slot.Attach(center.Container).MeasureWith(_ => center.Size))
499	            .AddSlot(slot => slot.Attach(_world.CreateEntity()).MeasureWith(_ => new Vector2(0, groupGap - rowGap)))
500	            .AddSlot(slot => slot.Attach(lerp.Container).MeasureWith(_ => lerp.Size))
501	            .Build();
502	    }
