544	/// Tag identifying the player-controlled circle in the camera demo.
545	public struct PlayerBallTag { }
546	
547	/// Reads keyboard input (WASD + arrows) and translates the tagged player entity,
548	/// clamping its position so the ball stays inside the boundary rectangle.
549	[With(typeof(PlayerBallTag), typeof(TransformComponent))]
550	public class PlayerBallMovementSystem : AEntitySetSystem<GameState>
551	{
552	    private readonly float _halfWidth;
553	    private readonly float _halfHeight;
554	    private readonly float _radius;
555	    private readonly float _speed;
556	
557	    public PlayerBallMovementSystem(World world, float halfWidth, float halfHeight, float radius, float speed)
558	        : base(world)
559	    {
560	        _halfWidth = halfWidth;
561	        _halfHeight = halfHeight;
562	        _radius = radius;
563	        _speed = speed;
564	    }
565	
566	    protected override void Update(GameState state, in Entity entity)
567	    {
568	        var keyboard = Keyboard.GetState();
569	        var dir = Vector2.Zero;
570	        if (keyboard.IsKeyDown(Keys.A) || keyboard.IsKeyDown(Keys.Left))  dir.X -= 1f;
571	        if (keyboard.IsKeyDown(Keys.D) || keyboard.IsKeyDown(Keys.Right)) dir.X += 1f;
572	        if (keyboard.IsKeyDown(Keys.W) || keyboard.IsKeyDown(Keys.Up))    dir.Y -= 1f;
573	        if (keyboard.IsKeyDown(Keys.S) || keyboard.IsKeyDown(Keys.Down))  dir.Y += 1f;
574	        if (dir != Vector2.Zero) dir.Normalize();
575	
576	        var transform = entity.Get<TransformComponent>();
577	        var next = transform.Position + dir * _speed * state.Time;
578	        next.X = MathHelper.Clamp(next.X, -_halfWidth + _radius, _halfWidth - _radius);
579	        next.Y = MathHelper.Clamp(next.Y, -_halfHeight + _radius, _halfHeight - _radius);
580	        transform.Position = next;
581	    }
582	}
