584	/// Polls the keyboard for camera-mode shortcuts (0–5, L) and forwards them
585	/// to the owning <see cref="CameraDemoScreen"/>. Edge-triggered: each key press
586	/// fires once per release-then-press cycle.
587	public class CameraDemoInputSystem : ISystem<GameState>
588	{
589	    private readonly CameraDemoScreen _screen;
590	    private KeyboardState _previous;
591	    public bool IsEnabled { get; set; } = true;
592	
593	    public CameraDemoInputSystem(CameraDemoScreen screen)
594	    {
595	        _screen = screen;
596	        _previous = Keyboard.GetState();
597	    }
598	
599	    public void Update(GameState state)
600	    {
601	        if (!IsEnabled) return;
602	        var current = Keyboard.GetState();
603	        bool Pressed(Keys k) => current.IsKeyDown(k) && !_previous.IsKeyDown(k);
604	
605	        if (Pressed(Keys.D0) || Pressed(Keys.NumPad0)) _screen.SetMode(CameraDemoScreen.Mode.Follow);
606	        if (Pressed(Keys.D1) || Pressed(Keys.NumPad1)) _screen.SetMode(CameraDemoScreen.Mode.FixedTL);
607	        if (Pressed(Keys.D2) || Pressed(Keys.NumPad2)) _screen.SetMode(CameraDemoScreen.Mode.FixedTR);
608	        if (Pressed(Keys.D3) || Pressed(Keys.NumPad3)) _screen.SetMode(CameraDemoScreen.Mode.FixedBR);
609	        if (Pressed(Keys.D4) || Pressed(Keys.NumPad4)) _screen.SetMode(CameraDemoScreen.Mode.FixedBL);
610	        if (Pressed(Keys.D5) || Pressed(Keys.NumPad5)) _screen.SetMode(CameraDemoScreen.Mode.FixedCenter);
611	        if (Pressed(Keys.L)) _screen.ToggleLerp();
612	        if (Pressed(Keys.Escape)) _screen.GoBackToLauncher();
613	
614	        _previous = current;
615	    }
